import { describe, expect, it, vi } from 'vitest';
import type { HookInput } from '../../types.js';
import { gitValidator } from '../../pretool/bash/git-validator.js';
import { createTestContext } from '../fixtures/test-context.js';

// Found by tests/hooks/verdict-probes: `git push origin HEAD:main` from a
// feature branch came back silent. validateBranchProtection returned early
// whenever the SESSION branch was not protected, so an explicitly named
// protected destination was never examined, while extractPushDestinations'
// own comment reads `HEAD:main -> ['main'] (still protected)`. A refspec that
// names main is a direct push to main from any branch. The #3455 allow
// (every destination non-protected) is untouched: it still allows.

vi.mock('node:child_process', () => ({
  execFileSync: vi.fn(() => ''),
}));

function bash(command: string): HookInput {
  return {
    tool_name: 'Bash',
    session_id: '00000000-0000-4000-8000-000000000000',
    tool_input: { command },
  } as unknown as HookInput;
}

// No project_dir in the payload, so resolveSessionBranch() returns ctx.branch
// and no git state is read: the verdict comes from the command text alone.
const onFeature = createTestContext({ branch: 'feat/probe' });

describe('git-validator: explicit protected destination from a feature branch', () => {
  it('denies git push origin HEAD:main', () => {
    const r = gitValidator(bash('git push origin HEAD:main'), onFeature);
    expect(r.continue).toBe(false);
    expect(r.hookSpecificOutput?.permissionDecision).toBe('deny');
    expect(String(r.stopReason)).toMatch(/protected branch 'main'/);
  });

  it('denies git push origin main (pushes the local main ref)', () => {
    const r = gitValidator(bash('git push origin main'), onFeature);
    expect(r.hookSpecificOutput?.permissionDecision).toBe('deny');
  });

  it('denies a refs/heads/ spelling with a leading +', () => {
    const r = gitValidator(bash('git push origin HEAD:+refs/heads/master'), onFeature);
    expect(r.hookSpecificOutput?.permissionDecision).toBe('deny');
  });

  it('still allows a push whose every destination is a feature branch (#3455)', () => {
    const r = gitValidator(bash('git push -u origin feat/probe'), onFeature);
    expect(r.continue).toBe(true);
    expect(r.hookSpecificOutput?.permissionDecision).toBeUndefined();
  });

  it('still allows a bare git push (destination unknowable from the text)', () => {
    const r = gitValidator(bash('git push'), onFeature);
    expect(r.continue).toBe(true);
    expect(r.hookSpecificOutput?.permissionDecision).toBeUndefined();
  });
});
